        INSERT INTO products
        (id, brand_id, category_id, sku, name, slug, base_price, discount_price, stock_quantity, specs, description, cpu, gpu, display, battery, weight, number_of_fans, os, is_active, created_at) VALUES
            (13, 1, 4, 'LAP-0013', 'Laptop Đồ Họa Apple MacBook Pro 14 M3 Pro', 'laptop-do-hoa-apple-macbook-pro-14-m3-pro', 46990000.00, 44990000.00, 16, '{"ram": "18GB", "storage": "512GB", "cpu": "Apple M3 Pro 11-Core CPU", "gpu": "Apple M3 Pro 14-Core GPU", "man_hinh": "14.2 inch Liquid Retina XDR"}'::jsonb, 'MacBook Pro 14 M3 Pro hướng tới nhà sáng tạo chuyên nghiệp với màn hình Liquid Retina XDR 120Hz, hiệu năng dựng hình và biên tập video mạnh mẽ cùng vỏ nhôm nguyên khối cao cấp.', 'Apple M3 Pro 11-Core CPU', 'Apple M3 Pro 14-Core GPU', '14.2 inch Liquid Retina XDR (3024 x 1964) 120Hz ProMotion, 1000 nits', '70 Wh Lithium-polymer (lên tới 17 giờ)', '1.55 kg', 2, 'macOS Sonoma', true, '2026-05-01 10:00:00+00'),
            (14, 1, 3, 'LAP-0014', 'Ultrabook Apple MacBook Air M2 13', 'ultrabook-apple-macbook-air-m2-13', 27990000.00, 24990000.00, 32, '{"ram": "8GB", "storage": "256GB", "cpu": "Apple M2 8-Core CPU", "gpu": "Apple M2 8-Core GPU", "man_hinh": "13.6 inch Liquid Retina"}'::jsonb, 'MacBook Air M2 giữ thiết kế mỏng nhẹ biểu tượng, hiệu năng đủ mạnh cho học tập và văn phòng, pin bền bỉ cả ngày và vận hành hoàn toàn yên tĩnh vì không có quạt.', 'Apple M2 8-Core CPU', 'Apple M2 8-Core GPU', '13.6 inch Liquid Retina (2560 x 1664), 500 nits, P3 Wide Color', '52.6 Wh Lithium-polymer (lên tới 18 giờ)', '1.24 kg', 0, 'macOS Sonoma', true, '2026-05-01 10:05:00+00'),
            (15, 2, 5, 'LAP-0015', 'Laptop Doanh Nhân Lenovo ThinkPad X1 Carbon Gen 12', 'laptop-doanh-nhan-lenovo-thinkpad-x1-carbon-gen-12', 42990000.00, 39990000.00, 13, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core Ultra 7 155U", "gpu": "Intel Graphics", "man_hinh": "14.0 inch WUXGA"}'::jsonb, 'ThinkPad X1 Carbon Gen 12 là chuẩn mực laptop doanh nhân: khung carbon siêu nhẹ 1.09kg, bàn phím ThinkPad trứ danh, bảo mật vPro và độ bền chuẩn quân đội MIL-STD 810H.', 'Intel Core Ultra 7 155U', 'Intel Graphics', '14.0 inch WUXGA (1920 x 1200) IPS, 400 nits, Anti-Glare', '57 Wh (lên tới 15 giờ)', '1.09 kg', 1, 'Windows 11 Pro', true, '2026-05-01 10:10:00+00'),
            (16, 2, 6, 'LAP-0016', 'Laptop Sinh Viên Lenovo IdeaPad Slim 5 14', 'laptop-sinh-vien-lenovo-ideapad-slim-5-14', 18990000.00, 16490000.00, 40, '{"ram": "16GB", "storage": "512GB", "cpu": "AMD Ryzen 7 8845HS", "gpu": "AMD Radeon 780M Graphics", "man_hinh": "14.0 inch WUXGA"}'::jsonb, 'IdeaPad Slim 5 14 cân bằng hiệu năng và giá cho sinh viên: chip Ryzen 7 mạnh, màn hình tỷ lệ 16:10 dễ làm việc, vỏ kim loại mỏng nhẹ và sạc nhanh qua USB-C.', 'AMD Ryzen 7 8845HS', 'AMD Radeon 780M Graphics', '14.0 inch WUXGA (1920 x 1200) IPS, 300 nits', '57 Wh', '1.46 kg', 1, 'Windows 11 Home', true, '2026-05-01 10:15:00+00'),
            (17, 2, 1, 'LAP-0017', 'Laptop Gaming Lenovo LOQ 15', 'laptop-gaming-lenovo-loq-15', 24990000.00, 22490000.00, 28, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core i5-13450HX", "gpu": "NVIDIA GeForce RTX 4050 6GB GDDR6", "man_hinh": "15.6 inch FHD"}'::jsonb, 'Lenovo LOQ 15 là dòng gaming phổ thông thừa hưởng tản nhiệt từ Legion, RTX 4050 chiến tốt eSports và game AAA ở FHD, phù hợp sinh viên mê game với ngân sách vừa phải.', 'Intel Core i5-13450HX', 'NVIDIA GeForce RTX 4050 6GB GDDR6', '15.6 inch FHD (1920 x 1080) 144Hz IPS, G-SYNC', '60 Wh', '2.38 kg', 2, 'Windows 11 Home', true, '2026-05-01 10:20:00+00'),
            (18, 3, 3, 'LAP-0018', 'Ultrabook Dell XPS 14 9440', 'ultrabook-dell-xps-14-9440', 44990000.00, 42990000.00, 11, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core Ultra 7 155H", "gpu": "Intel Arc Graphics", "man_hinh": "14.5 inch 3.2K"}'::jsonb, 'Dell XPS 14 9440 nổi bật với màn hình OLED 3.2K viền siêu mỏng, khung nhôm CNC, touchpad kính liền mạch và chip Core Ultra tích hợp NPU cho tác vụ AI.', 'Intel Core Ultra 7 155H (AI NPU)', 'Intel Arc Graphics', '14.5 inch 3.2K (3200 x 2000) OLED Touch 120Hz, 100% DCI-P3', '69.5 Wh', '1.68 kg', 2, 'Windows 11 Home', true, '2026-05-01 10:25:00+00'),
            (19, 3, 1, 'LAP-0019', 'Laptop Gaming Dell G15 5530', 'laptop-gaming-dell-g15-5530', 27990000.00, 25990000.00, 22, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core i7-13650HX", "gpu": "NVIDIA GeForce RTX 4050 6GB GDDR6", "man_hinh": "15.6 inch FHD"}'::jsonb, 'Dell G15 5530 mang phong cách Alienware với tản nhiệt Vapor Chamber, màn hình 165Hz và cấu hình HX mạnh, là lựa chọn gaming tầm trung bền bỉ của Dell.', 'Intel Core i7-13650HX', 'NVIDIA GeForce RTX 4050 6GB GDDR6', '15.6 inch FHD (1920 x 1080) 165Hz, G-SYNC', '56 Wh', '2.65 kg', 2, 'Windows 11 Home', true, '2026-05-01 10:30:00+00'),
            (20, 3, 2, 'LAP-0020', 'Laptop Văn Phòng Dell Inspiron 14 5440', 'laptop-van-phong-dell-inspiron-14-5440', 17990000.00, 15990000.00, 36, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core i5-1334U", "gpu": "Intel Iris Xe Graphics", "man_hinh": "14.0 inch FHD+"}'::jsonb, 'Inspiron 14 5440 gọn nhẹ cho công việc hằng ngày: màn hình 16:10 rộng rãi, hiệu năng văn phòng mượt mà, đầy đủ cổng kết nối và mức giá dễ tiếp cận.', 'Intel Core i5-1334U', 'Intel Iris Xe Graphics', '14.0 inch FHD+ (1920 x 1200) IPS, Anti-Glare', '54 Wh', '1.54 kg', 1, 'Windows 11 Home', true, '2026-05-01 10:35:00+00'),
            (21, 4, 6, 'LAP-0021', 'Laptop Sinh Viên HP Pavilion 15', 'laptop-sinh-vien-hp-pavilion-15', 13990000.00, 11990000.00, 50, '{"ram": "8GB", "storage": "512GB", "cpu": "AMD Ryzen 5 7530U", "gpu": "AMD Radeon Graphics", "man_hinh": "15.6 inch FHD"}'::jsonb, 'HP Pavilion 15 là lựa chọn quốc dân cho sinh viên: màn hình lớn 15.6 inch, hiệu năng ổn định cho học tập và giải trí, loa B&O và thiết kế trẻ trung.', 'AMD Ryzen 5 7530U', 'AMD Radeon Graphics', '15.6 inch FHD (1920 x 1080) IPS, 250 nits', '41 Wh', '1.75 kg', 1, 'Windows 11 Home', true, '2026-05-01 10:40:00+00'),
            (22, 4, 5, 'LAP-0022', 'Laptop Doanh Nhân HP EliteBook 840 G11', 'laptop-doanh-nhan-hp-elitebook-840-g11', 32990000.00, 30990000.00, 15, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core Ultra 7 155U", "gpu": "Intel Graphics", "man_hinh": "14.0 inch WUXGA"}'::jsonb, 'EliteBook 840 G11 dành cho doanh nghiệp với bảo mật HP Wolf Security, khung nhôm nhẹ 1.36kg, camera 5MP và khả năng nâng cấp, sửa chữa thân thiện IT.', 'Intel Core Ultra 7 155U', 'Intel Graphics', '14.0 inch WUXGA (1920 x 1200) IPS, 400 nits', '56 Wh', '1.36 kg', 1, 'Windows 11 Pro', true, '2026-05-01 10:45:00+00'),
            (23, 5, 4, 'LAP-0023', 'Laptop Đồ Họa ASUS ProArt P16', 'laptop-do-hoa-asus-proart-p16', 69990000.00, 66990000.00, 8, '{"ram": "32GB", "storage": "1TB", "cpu": "Intel Core Ultra 9 185H", "gpu": "NVIDIA GeForce RTX 4070 8GB GDDR6", "man_hinh": "16.0 inch 4K"}'::jsonb, 'ASUS ProArt P16 sinh ra cho nhà sáng tạo: màn hình OLED 4K chuẩn màu Pantone, RTX 4070, núm xoay ASUS DialPad và đầy đủ cổng SD 7.0 cho quay dựng chuyên nghiệp.', 'Intel Core Ultra 9 185H (AI NPU)', 'NVIDIA GeForce RTX 4070 8GB GDDR6', '16.0 inch 4K (3840 x 2400) OLED Touch, 100% DCI-P3, Delta-E < 2', '90 Wh', '1.85 kg', 2, 'Windows 11 Pro', true, '2026-05-01 10:50:00+00'),
            (24, 6, 6, 'LAP-0024', 'Laptop Sinh Viên Acer Aspire Lite 15', 'laptop-sinh-vien-acer-aspire-lite-15', 11490000.00, 9990000.00, 57, '{"ram": "8GB", "storage": "512GB", "cpu": "AMD Ryzen 5 7430U", "gpu": "AMD Radeon Graphics", "man_hinh": "15.6 inch FHD"}'::jsonb, 'Acer Aspire Lite 15 tập trung vào nhu cầu thiết yếu của sinh viên với mức giá mềm: màn hình FHD lớn, trọng lượng nhẹ và pin đủ cho một ngày học.', 'AMD Ryzen 5 7430U', 'AMD Radeon Graphics', '15.6 inch FHD (1920 x 1080) IPS, Acer ComfyView', '45 Wh', '1.59 kg', 1, 'Windows 11 Home', true, '2026-05-01 10:55:00+00'),
            (25, 10, 3, 'LAP-0025', 'Ultrabook LG Gram 16', 'ultrabook-lg-gram-16', 36990000.00, 34490000.00, 18, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core Ultra 7 155H", "gpu": "Intel Arc Graphics", "man_hinh": "16.0 inch WQXGA"}'::jsonb, 'LG Gram 16 phá vỡ giới hạn trọng lượng: màn hình 16 inch nhưng chỉ nặng 1.19kg nhờ hợp kim magie, pin 77Wh dùng cả ngày, đạt chuẩn bền MIL-STD 810H.', 'Intel Core Ultra 7 155H (AI NPU)', 'Intel Arc Graphics', '16.0 inch WQXGA (2560 x 1600) IPS, 99% DCI-P3', '77 Wh', '1.19 kg', 2, 'Windows 11 Home', true, '2026-05-01 11:00:00+00'),
            (26, 7, 2, 'LAP-0026', 'Laptop Văn Phòng MSI Modern 15', 'laptop-van-phong-msi-modern-15', 16990000.00, 14990000.00, 30, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core i7-1355U", "gpu": "Intel Iris Xe Graphics", "man_hinh": "15.6 inch FHD"}'::jsonb, 'MSI Modern 15 hướng tới dân văn phòng năng động: thiết kế tối giản, bản lề mở 180 độ, đầy đủ cổng HDMI/USB-C và hiệu năng Core i7 tiết kiệm điện.', 'Intel Core i7-1355U', 'Intel Iris Xe Graphics', '15.6 inch FHD (1920 x 1080) IPS', '53.8 Wh', '1.70 kg', 1, 'Windows 11 Home', true, '2026-05-01 11:05:00+00'),
            (27, 3, 5, 'LAP-0027', 'Laptop Doanh Nhân Dell Latitude 5550', 'laptop-doanh-nhan-dell-latitude-5550', 29990000.00, 27990000.00, 19, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core Ultra 7 165U vPro", "gpu": "Intel Graphics", "man_hinh": "15.6 inch FHD"}'::jsonb, 'Latitude 5550 là dòng doanh nghiệp chủ lực của Dell với vPro quản trị từ xa, độ bền cao, bàn phím êm và chính sách bảo hành onsite phù hợp đội IT.', 'Intel Core Ultra 7 165U vPro', 'Intel Graphics', '15.6 inch FHD (1920 x 1080) IPS, 250 nits', '54 Wh', '1.62 kg', 1, 'Windows 11 Pro', true, '2026-05-01 11:10:00+00'),
            (28, 4, 2, 'LAP-0028', 'Laptop Văn Phòng HP ProBook 445 G11', 'laptop-van-phong-hp-probook-445-g11', 19490000.00, 17490000.00, 25, '{"ram": "16GB", "storage": "512GB", "cpu": "AMD Ryzen 7 7735U", "gpu": "AMD Radeon 680M Graphics", "man_hinh": "14.0 inch WUXGA"}'::jsonb, 'HP ProBook 445 G11 cân bằng bảo mật doanh nghiệp nhỏ và giá: chip Ryzen 7 tiết kiệm điện, khung nhôm nhẹ, camera IR và vân tay đăng nhập nhanh.', 'AMD Ryzen 7 7735U', 'AMD Radeon 680M Graphics', '14.0 inch WUXGA (1920 x 1200) IPS, 300 nits', '56 Wh', '1.39 kg', 1, 'Windows 11 Home', true, '2026-05-01 11:15:00+00'),
            (29, 7, 4, 'LAP-0029', 'Laptop Đồ Họa MSI Stealth 16 Studio', 'laptop-do-hoa-msi-stealth-16-studio', 54990000.00, 51990000.00, 9, '{"ram": "32GB", "storage": "1TB", "cpu": "Intel Core i7-13700H", "gpu": "NVIDIA GeForce RTX 4070 8GB GDDR6", "man_hinh": "16.0 inch QHD+"}'::jsonb, 'MSI Stealth 16 Studio kết hợp thân hình mỏng của ultrabook với sức mạnh workstation: màn Mini-LED 240Hz, RTX 4070 và tản nhiệt Cooler Boost 5 cho render 3D, dựng phim.', 'Intel Core i7-13700H', 'NVIDIA GeForce RTX 4070 8GB GDDR6', '16.0 inch QHD+ (2560 x 1600) Mini-LED 240Hz, 100% DCI-P3', '99.9 Wh', '1.99 kg', 2, 'Windows 11 Pro', true, '2026-05-01 11:20:00+00'),
            (30, 12, 6, 'LAP-0030', 'Laptop Sinh Viên Huawei MateBook D 16', 'laptop-sinh-vien-huawei-matebook-d-16', 15990000.00, 13990000.00, 39, '{"ram": "16GB", "storage": "512GB", "cpu": "Intel Core i5-12450H", "gpu": "Intel UHD Graphics", "man_hinh": "16.0 inch FHD+"}'::jsonb, 'Huawei MateBook D 16 nổi bật với màn hình 16 inch viền mỏng trong thân máy 15.6 inch, bàn phím có numpad, ăng-ten Wi-Fi tầm xa và mức giá sinh viên dễ tiếp cận.', 'Intel Core i5-12450H', 'Intel UHD Graphics', '16.0 inch FHD+ (1920 x 1200) IPS, 300 nits', '56 Wh', '1.68 kg', 1, 'Windows 11 Home', true, '2026-05-01 11:25:00+00');
