-- ============================================================================
-- V53 (devdata): Seed 18 additional sample products (ids 13-30), raising the
-- demo catalog from 12 to 30 products.
--
-- Placement: db/devdata ONLY, following V3. Sample data must never seed a
-- production database (ProductionMigrationSmokeTest asserts a fresh
-- db/migration chain contains 0 products). The dev profile loads both
-- classpath:db/migration and classpath:db/devdata, so this file still runs
-- as a normal Flyway migration in development.
--
-- Guarded like V38: the whole block runs only when the 12 known demo
-- products from V3 are present, and it is idempotent (skips if product 13
-- already exists). Each product gets one primary image in
-- /uploads/products/<slug>.jpg and two variants priced in VND, mirroring
-- the V38 variant style. Image files live in uploads/products/ in the repo.
-- ============================================================================

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM products WHERE id BETWEEN 1 AND 12) = 12
       AND NOT EXISTS (SELECT 1 FROM products WHERE id = 13) THEN

        -- Colors used by the new variants (same palette as V38)
        ON CONFLICT (name) DO UPDATE SET hex_code = EXCLUDED.hex_code;

        -- Products 13-30

        -- Primary images (files in uploads/products/, named after the slug)

        -- Two variants per product (VND prices, V38 style)

        -- Resync identity sequences after explicit-id inserts
        PERFORM setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM products), 1));
        PERFORM setval(pg_get_serial_sequence('product_images', 'id'), COALESCE((SELECT MAX(id) FROM product_images), 1));
        PERFORM setval(pg_get_serial_sequence('product_variants', 'id'), COALESCE((SELECT MAX(id) FROM product_variants), 1));
    END IF;
END $$;
